import { useId } from 'react';
import { BatikPatternDef } from '../../app/MaskotAksa';

interface OnboardingSceneArtProps {
  step: number;
}

/**
 * Ilustrasi vektor animasi penuh untuk Onboarding Screen 1–3.
 * Menggunakan geometri Figma Aksa + blangkon batik vektor tajam tanpa bitmap berat,
 * dengan rig animasi independen per adegan (membaca, menulis goresan, dan memindai Lensa).
 */
export function OnboardingSceneArt({ step }: OnboardingSceneArtProps) {
  if (step === 0) return <SceneKenaliAksara />;
  if (step === 1) return <SceneCobaGoresan />;
  return <SceneTemukanBunyi />;
}

